def add(w, lang, pos, b, origin, dfn, ex, etym, pat, say="", path="", alt=None, hom=False):
    rows.append({
        "w": w, "lang": lang, "pos": pos, "b": b, "origin": origin,
        "def": dfn, "ex": ex, "etym": etym, "pat": pat,
        "say": say, "path": path, "alt": alt or [], "hom": hom,
    })

